from __future__ import absolute_import, division, print_function,\
    unicode_literals
from taf.ul.trs_e2e_fw.lib.traffic.capture.tshark_capture import TsharkCapture
from taf.ul.trs_e2e_fw.lib.traffic.capture.tcpdumpcapture import TcpdumpCapture
from taf.ul.trs_e2e_fw.lib.traffic.capture.oam_capture import OamCapture
from taf.ul.trs_e2e_fw.lib.traffic.capture.vdu_capture import VduCapture
from taf.ul.trs_e2e_fw.lib.traffic.capture.cu_capture import CuCapture
from builtins import object
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler
from taf.ul.trs_e2e_fw.lib.traffic.capture.tool_base import ToolBase
from future import standard_library
standard_library.install_aliases()


class ToolFactory(object):

    def __init__(self, capture_device):
        self.config = ConfigHandler.get_config()
        self.capture_device = capture_device

    def get_tool_obj(self):
        return self.choose_capture_tool()

    def choose_capture_tool(self):
        capture_tool = get_config_variable(['traffic_capture', self.capture_device, 'tool'])
        for tool in ToolBase.__subclasses__():
            # print("toolbase subclass in choose capture:{}".format(tool))
            if tool.check_tool(capture_tool):
                return tool(self.config, self.capture_device)
